import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.Dh3ZG9qC.js";const f=JSON.parse('{"title":"认识 Gamer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),l={name:"guide/getting-started.md"};function i(o,t,h,n,m,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="认识-gamer" tabindex="-1">认识 Gamer <a class="header-anchor" href="#认识-gamer" aria-label="Permalink to &quot;认识 Gamer&quot;">​</a></h1><p>Gamer 将 Android 设备的投屏、操作和自动化放进浏览器工作台。适合把重复操作编排成流程，也可以先录制一次操作，再从视频中提取模板、整理脚本。</p><h2 id="先走通一条流程" tabindex="-1">先走通一条流程 <a class="header-anchor" href="#先走通一条流程" aria-label="Permalink to &quot;先走通一条流程&quot;">​</a></h2><ol><li>按<a href="./installation.html">安装与首次启动</a>运行 Gamer，完成管理员密码设置。</li><li>在「插件」页安装需要的官方插件，首次使用自动化时安装 <code>gamer-yaml</code>。</li><li><a href="./devices.html">接入设备</a>，在工作台选择 Android 应用并建立投屏连接。</li><li>选择一个配置，进入「自动化」创建脚本。</li><li>加入等待、点击或查找模板步骤，保存后运行，查看下方状态条。</li></ol><p>没有预置游戏脚本时，空白工作台是正常状态。先安装插件，再创建自己的内容。</p><h2 id="五个概念" tabindex="-1">五个概念 <a class="header-anchor" href="#五个概念" aria-label="Permalink to &quot;五个概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>负责什么</th><th>例子</th></tr></thead><tbody><tr><td>设备</td><td>决定在哪台 Android 设备上运行</td><td>USB serial、<code>emulator-5554</code></td></tr><tr><td>应用</td><td>决定设备上启动哪个 Android 应用</td><td><code>com.example.game</code></td></tr><tr><td>配置包</td><td>保存脚本、模板、映射和视频项目</td><td><code>daily-config</code></td></tr><tr><td>插件</td><td>提供功能界面或执行能力</td><td><code>gamer-yaml</code></td></tr><tr><td>任务</td><td>把执行入口、参数、设备与调度组合起来</td><td>每天执行签到流程</td></tr></tbody></table><p>应用与配置分别选择。配置包的名字不需要等于 Android 应用包名；同一个应用可以使用不同配置。</p><h2 id="按需要阅读" tabindex="-1">按需要阅读 <a class="header-anchor" href="#按需要阅读" aria-label="Permalink to &quot;按需要阅读&quot;">​</a></h2><ul><li>只想远程操作：先看<a href="./devices.html">设备连接</a>和<a href="./workbench.html">工作台</a>。</li><li>想编写脚本：看<a href="./automation.html">自动化与函数</a>、<a href="./templates.html">模板匹配</a>和 <a href="./../guides/yaml-tutorial.html">YAML 案例</a>。</li><li>想用键盘玩游戏：看<a href="./keymap.html">按键映射</a>。</li><li>想从录制整理流程：看<a href="./video.html">视频与录制</a>。</li><li>想做自己的扩展：从<a href="./../development/overview.html">插件开发概览</a>开始。</li></ul>',10)])])}const u=a(l,[["render",i]]);export{f as __pageData,u as default};
